--
CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertRandomJobs` ()   BEGIN
    DECLARE last_date DATETIME;
    DECLARE i INT DEFAULT 0;
    DECLARE num_rows INT;
    DECLARE counter INT DEFAULT 1;

    -- Get the last created_at date
    SELECT MAX(created_at) INTO last_date FROM system_queue_job;
    
    -- If no data exists, set last_date to 5 days ago
    IF last_date IS NULL THEN
        SET last_date = NOW() - INTERVAL 1 DAY;
    END IF;
    
    START TRANSACTION;
    
    WHILE i < 10 DO
        SET last_date = DATE_SUB(last_date, INTERVAL 1 DAY);  
        SET num_rows = FLOOR(RAND() * (80000 - 20000 + 1)) + 20000;  -- Generate random number between 20000 and 80000
        
        -- Insert multiple random rows
        WHILE num_rows > 0 DO
            VALUES (
                UUID(), 
                'email', 
                CONCAT('Data no ', counter, ' for date ', last_date),
                0, 
                1, 
                last_date, 
                NULL
            );
            
            SET num_rows = num_rows - 1;
            SET counter = counter + 1;
        END WHILE;
        
        SET i = i + 1;
    END WHILE;

    COMMIT;
END$$

DELIMITER ;

